import java.util.*;
class Solution { public int networkDelayTime(int[][]e,int n,int k){List<int[]>[]g=new List[n+1];for(int i=1;i<=n;i++)g[i]=new ArrayList<>();for(int[]x:e)g[x[0]].add(new int[]{x[1],x[2]});int[]d=new int[n+1];Arrays.fill(d,1<<30);d[k]=0;PriorityQueue<int[]>q=new PriorityQueue<>((a,b)->a[1]-b[1]);q.offer(new int[]{k,0});while(!q.isEmpty()){int[]u=q.poll();if(u[1]!=d[u[0]])continue;for(int[]v:g[u[0]])if(d[v[0]]>u[1]+v[1]){d[v[0]]=u[1]+v[1];q.offer(new int[]{v[0],d[v[0]]});}}int z=0;for(int i=1;i<=n;i++){if(d[i]==1<<30)return -1;z=Math.max(z,d[i]);}return z;} }